        },
        {
            "id": "wait15min",
            "type": "core.logic.delay",
            "typeVersion": delay_version,
            "display": {"label": "Wait 15 Minutes"},
            "inputs": {
                "timerType": "timeDuration",
                "timerPreset": "PT15M"
            }
        },
        {
            "id": "done",
            "type": "core.control.end",
            "typeVersion": end_version,
            "display": {"label": "End"}
        }
    ],
    "edges": [
        {
            "id": "edge_start_output_wait15min_input",
