            "sourcePort": "output",
            "targetNodeId": "wait15min",
            "targetPort": "input"
        },
        {
            "id": "edge_wait15min_output_done_input",
            "sourceNodeId": "wait15min",
            "sourcePort": "output",
            "targetNodeId": "done",
            "targetPort": "input"
        }
    ],
    "definitions": [
        # trigger definition already in file — keep it
        {
            "nodeType": "core.trigger.manual",
            "version": "1.0",
            "category": "trigger",
            "description": "Start the process manually",
            "tags": ["trigger", "start", "manual"],
            "sortOrder": 80,
            "display": {"label": "Manual trigger", "icon": "play", "shape": "circle"},
            "handleConfiguration": [
                {
                    "position": "right",
                    "handles": [{"id": "output", "type": "source", "handleType": "output", "showButton": True, "constraints": {"forbiddenTargetCategories": ["trigger"]}}],
                    "visible": True
                }
            ],
            "model": {"type": "bpmn:StartEvent", "entryPointId": True},
            "outputDefinition": {"output": {"type": "object", "description": "Data passed when manually triggering the process.", "source": "null", "var": "output"}},
            "toolbarExtensions": {"design": {"actions": [{"id": "change-trigger-type", "icon": "square-mouse-pointer", "label": "Change trigger type"}]}}
