            "done": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
        }
    }
}

out_path = '/work/output/artifacts/skill-flow-delay/DelayDemo/DelayDemo/DelayDemo.flow'
with open(out_path, 'w') as f:
    json.dump(flow, f, indent=2)
print("Written:", out_path)
print("Delay typeVersion used:", delay_version)
